import sys

def solve():
    N = int(input())
    a = list(map(int, input().split()))

    # Initialize prefix sums
    prefix_sum = [0] * (3*N + 1)
    for i in range(1, 3*N + 1):
        prefix_sum[i] = prefix_sum[i-1] + a[i-1]

    # Initialize dp array
    dp = [[-float('inf')] * (N+1) for _ in range(3*N+1)]
    dp[0][0] = 0

    # Fill dp array
    for i in range(1, 3*N + 1):
        for j in range(min(i, N) + 1):
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j-1] + (prefix_sum[i] - prefix_sum[i//2]) - (prefix_sum[i//2] - prefix_sum[(i-j)//2]))
            if i > j:
                dp[i][j] = max(dp[i][j], dp[i-1][j])

    # Find maximum score
    max_score = max(dp[3*N])
    print(max_score)

if __name__ == "__main__":
    solve()
